param([string]$WorkspaceRoot="$env:USERPROFILE\BlackDuckSEWorkspace",[string]$BaseUrl="http://127.0.0.1:3000")
$ErrorActionPreference='Stop'; $ver='22.3.3.1'; $run=Get-Date -Format 'yyyyMMdd-HHmmss'; $out=Join-Path $WorkspaceRoot "robot-results\intelligence-v$ver-$run"; New-Item -ItemType Directory -Force $out|Out-Null
$R=New-Object System.Collections.Generic.List[object]
function Result($n,$p,$d){$R.Add([pscustomobject]@{name=$n;status=$(if($p){'PASS'}else{'FAIL'});detail=[string]$d});Write-Host "$(if($p){'PASS'}else{'FAIL'}): $n - $d" -ForegroundColor $(if($p){'Green'}else{'Red'})}
function GetApi($p){Invoke-RestMethod -Uri ($BaseUrl+$p) -TimeoutSec 180}
function Send($m,$p,$b){Invoke-RestMethod -Method $m -Uri ($BaseUrl+$p) -ContentType 'application/json' -Body ($b|ConvertTo-Json -Depth 50) -TimeoutSec 1200}
function Canon($o){$j=$o|ConvertTo-Json -Depth 100 -Compress; $sha=[Security.Cryptography.SHA256]::Create(); ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($j)))).Replace('-','')}
function Flat($o){$o|ConvertTo-Json -Depth 100 -Compress}
$id=$(if($env:BDSE_ROBOT_RECORD_ID){[int]$env:BDSE_ROBOT_RECORD_ID}else{$null}); $marker="ROBOT-EVIDENCE-$run"; $metric="Reduce release validation time by 37 percent [$marker]"; $champion="Jordan Robot, Director of Release Assurance [$marker]"
try{$h=GetApi '/api/health';Result 'Health' ($h.status-eq'running') ($h|ConvertTo-Json -Compress)}catch{Result 'Health' $false $_.Exception.Message}
try{$hist=@(GetApi '/api/history-v3');if($hist.Count-eq 1-and$hist[0]-is[Array]){$hist=@($hist[0])};$rec=$hist|?{$_.partner_name-like'Robot QA Partner*'}|Select-Object -First 1;if(!$rec){throw 'No Robot QA record. Run Full Robot v22.3.1.2 first.'};$id=$(if($env:BDSE_ROBOT_RECORD_ID){[int]$env:BDSE_ROBOT_RECORD_ID}else{[int]$rec.id});Result 'Select fresh Robot QA record' $true "ID=$id"}catch{Result 'Select fresh Robot QA record' $false $_.Exception.Message}
if($id){
 try{$before=GetApi "/api/call-report-v4/$id";$beforeHash=Canon $before.prepared_call;$beforeText=Flat $before.prepared_call;$aud0=@(GetApi "/api/prep-query-audit/$id");if($aud0.Count-eq 1-and$aud0[0]-is[Array]){$aud0=@($aud0[0])};Result 'Capture baseline structured output' ($beforeHash.Length-eq 64) $beforeHash}catch{Result 'Capture baseline structured output' $false $_.Exception.Message}
 try{$body=@{answers=@(@{question_key='robot_metric_v2232';section='MEDDPICC';question='What measurable result is required?';answer=$metric;notes='Synthetic intelligence rerun assertion';importance='High';confirmed=$true},@{question_key='robot_champion_v2232';section='MEDDPICC';question='Who is the champion?';answer=$champion;notes='Synthetic intelligence rerun assertion';importance='High';confirmed=$true})};$s=Send PUT "/api/call-report-v4/$id/answers" $body;Result 'Save changed evidence' ($s.saved-eq 2) "saved=$($s.saved); marker=$marker"}catch{Result 'Save changed evidence' $false $_.Exception.Message}
 try{$reload=GetApi "/api/call-report-v4/$id";$txt=Flat $reload.answers;Result 'Reload changed evidence' ($txt.Contains($marker)) $marker}catch{Result 'Reload changed evidence' $false $_.Exception.Message}
 try{$resynth=Send POST "/api/post-meeting-resynthesis/$id" @{};Result 'Invoke production LLM resynthesis' ($resynth.success-eq $true) "answer_count=$($resynth.answer_count)"}catch{Result 'Invoke production LLM resynthesis' $false $_.Exception.Message}
 try{$after=GetApi "/api/call-report-v4/$id";$afterHash=Canon $after.prepared_call;$afterText=Flat $after.prepared_call;Result 'Structured output hash changed' ($afterHash-ne$beforeHash) "before=$beforeHash after=$afterHash";Result 'Updated evidence propagated to structured output' ($afterText.Contains($marker)-or($afterText-match'37 percent')-or($afterText-match'Jordan Robot')) 'marker or deterministic evidence present'}catch{Result 'Structured output hash changed' $false $_.Exception.Message}
 try{$aud1=@(GetApi "/api/prep-query-audit/$id");if($aud1.Count-eq 1-and$aud1[0]-is[Array]){$aud1=@($aud1[0])};$stage5=@($aud1|?{$_.stage-match'^5\s|Post-Meeting Resynthesis'});Result 'New LLM audit created' ($aud1.Count-gt$aud0.Count-and$stage5.Count-gt 0) "before=$($aud0.Count) after=$($aud1.Count) stage5=$($stage5.Count)";if($stage5.Count){$a=$stage5|Select-Object -Last 1;Result 'LLM audit has model and structured response' (![string]::IsNullOrWhiteSpace($a.model)-and![string]::IsNullOrWhiteSpace($a.response_json)) "model=$($a.model)"}}catch{Result 'New LLM audit created' $false $_.Exception.Message}
 try{$payload=@{call_prep_id=$id;partner_name=$after.partner_name;presenter='Regression Robot';result=$after.prepared_call};$e=Send POST '/api/research-exports' $payload;Result 'Regenerate updated artifacts' ($e.report_name-and$e.deck_name) "$($e.report_name) | $($e.deck_name)";$names=@($e.report_name,$e.deck_name);Add-Type -AssemblyName System.IO.Compression.FileSystem;foreach($name in $names){$f=Join-Path (Join-Path $WorkspaceRoot 'exports') $name;if(!(Test-Path $f)){throw "Missing $f"};$z=[IO.Compression.ZipFile]::OpenRead($f);$t='';foreach($en in $z.Entries){if($en.FullName-match'\.xml$'){$sr=New-Object IO.StreamReader($en.Open());$t+=$sr.ReadToEnd();$sr.Dispose()}};$z.Dispose();$bad=([regex]::Matches($t,'\[object Object\]|\bundefined\b|\bnull\b','IgnoreCase')).Count;$has=$t.Contains($marker)-or$t.Contains('37 percent')-or$t.Contains('Jordan Robot');Result "Artifact content $([IO.Path]::GetExtension($name))" ($bad-eq 0-and$has) "markers=$bad updatedEvidence=$has file=$name"}}catch{Result 'Regenerate updated artifacts' $false $_.Exception.Message}
 $js=Join-Path $PSScriptRoot 'Intelligence-UI-v22.3.2.js';$jr=Join-Path $out 'playwright-intelligence.json';try{Push-Location $WorkspaceRoot;& node $js $BaseUrl $jr $id $marker;$ec=$LASTEXITCODE;Pop-Location;Result 'Playwright updated-record validation' ($ec-eq 0) "exit=$ec"}catch{try{Pop-Location}catch{};Result 'Playwright updated-record validation' $false $_.Exception.Message}
}
$fail = @($R | Where-Object { $_.status -eq 'FAIL' });$report=[ordered]@{version=$ver;run=$run;record_id=$id;synthetic_data=$true;marker=$marker;overall=$(if($fail.Count){'FAIL'}else{'PASS'});results=$R};$report|ConvertTo-Json -Depth 20|Set-Content (Join-Path $out 'intelligence-report.json') -Encoding UTF8;$R|Format-Table -AutoSize;Write-Host "OVERALL: $($report.overall)" -ForegroundColor $(if($fail.Count){'Red'}else{'Green'});Write-Host "REPORT: $(Join-Path $out 'intelligence-report.json')";if ($fail.Count -gt 0) {
    exit 1
}
exit 0

